(()=>{'use strict';const O=MartinsOrcamentos,P=MartinsPersistenciaRdo,V=MartinsVendasObras,$=id=>document.getElementById(id),form=$('form-novo-orcamento-venda');if(!form)return;let snapshot=null;
const extra=document.createElement('section');extra.className='orc-detalhes';extra.innerHTML='<h4>Identificação e escopo da proposta</h4><label>Objeto / resumo dos serviços<textarea id="orc-objeto" maxlength="2000" rows="2"></textarea></label><div class="orc-grid"><label>CPF/CNPJ do cliente<input id="orc-cliente-doc" maxlength="100"></label><label>Contato do cliente<input id="orc-cliente-tel" maxlength="100"></label><label>Cidade / local<input id="orc-cliente-cidade" maxlength="200"></label></div><label>Observações e condições complementares<textarea id="orc-observacoes" maxlength="2000" rows="3"></textarea></label>';form.firstElementChild.after(extra);
const css=document.createElement('style');css.textContent='#modal-novo-orcamento-venda>div{max-width:1040px;width:100%;box-sizing:border-box}#form-novo-orcamento-venda label{display:block;font-weight:700;margin-bottom:6px}#form-novo-orcamento-venda input,#form-novo-orcamento-venda select,#form-novo-orcamento-venda textarea{width:100%;min-width:0;min-height:42px;padding:9px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;box-sizing:border-box}.orc-detalhes{padding:14px;background:#f8fafc;border:1px solid #cbd5e1;border-radius:12px}.orc-detalhes h4{font-weight:800;margin-bottom:10px}.orc-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.orc-item{display:grid;grid-template-columns:minmax(160px,3fr) 80px 95px 110px 110px 44px;gap:9px;align-items:end;padding:12px;background:#fff;border:1px solid #cbd5e1;border-radius:10px}.orc-item output{display:block;min-height:42px;padding:9px;font-weight:800;overflow-wrap:anywhere}.orc-item button{min-height:42px}.orc-item label{font-size:11px}@media(max-width:760px){.orc-grid{grid-template-columns:1fr}.orc-item{grid-template-columns:repeat(2,minmax(0,1fr))}.orc-item label:first-child{grid-column:1/-1}}';document.head.append(css);
function actor(){let s;try{s=JSON.parse(sessionStorage.getItem('cm_active_user')||'null')}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!V.canSell(u)||!s||id(s)!==id(u)||s.perfil!==u.perfil||s.status==='Inativo')throw Error('Entre com perfil autorizado ao Comercial');return u.usuario||u.email||u.nome;}
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});function totals(){let total=0;for(const [i,row]of [...$('lista-itens-orcamento-form').children].entries()){const it=window.linhasOrcamentoModal[i],value=Math.round(Number(it.qtd)*Number(it.precoUnit)*100)/100;row.querySelector('output').textContent=Number.isFinite(value)&&value>=0?money(value):'Confira valores';total+=value;}const badge=$('orc-total-geral-badge');badge.textContent=Number.isFinite(total)&&total>=0?money(total):'Confira valores';}
window.renderLinhasItemOrcamentoModal=function(){const host=$('lista-itens-orcamento-form');host.replaceChildren();for(const [index,it]of (window.linhasOrcamentoModal||[]).entries()){const row=document.createElement('div');row.className='orc-item';for(const [key,label,type]of [['desc','Produto / serviço','text'],['unid','Unidade','text'],['qtd','Quantidade','number'],['precoUnit','Valor unitário (R$)','number']]){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');input.type=type;input.value=it[key]??'';input.required=true;input.setAttribute('aria-label',label+' do item '+(index+1));if(type==='number'){input.min=key==='qtd'?'0.001':'0';input.step=key==='qtd'?'any':'.01';}else input.maxLength=key==='desc'?500:30;input.oninput=()=>{it[key]=input.value;totals();form.dispatchEvent(new Event('input',{bubbles:true}));};l.append(input);row.append(l);}const l=document.createElement('label');l.textContent='Subtotal';l.append(document.createElement('output'));const b=document.createElement('button');b.type='button';b.textContent='×';b.setAttribute('aria-label','Remover item '+(index+1));b.onclick=()=>{window.linhasOrcamentoModal.splice(index,1);window.renderLinhasItemOrcamentoModal();form.dispatchEvent(new Event('input',{bubbles:true}));};row.append(l,b);host.append(row);}totals();};
const open=window.abrirModalNovoOrcamentoVenda;window.abrirModalNovoOrcamentoVenda=function(...args){open.apply(this,args);snapshot=localStorage.getItem(V.QUOTES);window.linhasOrcamentoModal=[{desc:'',unid:'Un',qtd:1,precoUnit:0}];window.renderLinhasItemOrcamentoModal();window.martinsFormularios?.markClean(form);};
window.salvarNovoOrcamentoVendaForm=async function(event){event?.preventDefault();const submit=form.querySelector('button[type=submit]');if(submit.disabled)return;submit.disabled=true;try{const by=actor(),raw=localStorage.getItem(V.QUOTES);if(raw!==snapshot)throw Error('Orçamentos alterados em outra aba; mantenha o preenchimento e confira antes de salvar.');const value=id=>$(id).value;const result=O.create(window.getOrcamentosVendasDb(),{empresa:value('orc-inp-empresa'),cliente:value('orc-inp-cliente'),validade:value('orc-inp-validade'),condicoes:value('orc-inp-condicoes'),prazo:value('orc-inp-prazo'),objeto:value('orc-objeto'),observacoes:value('orc-observacoes'),clienteDetalhe:{doc:value('orc-cliente-doc'),tel:value('orc-cliente-tel'),cidade:value('orc-cliente-cidade')},itens:window.linhasOrcamentoModal},by);await P.withLock(navigator.locks,()=>{if(actor()!==by)throw Error('Sessão alterada; confira novamente');P.commit(localStorage,[{key:V.QUOTES,expected:raw,value:result.rows}],{actor:by});});window.martinsFormularios?.markClean(form);window.fecharModalNovoOrcamentoVenda();window.renderListaOrcamentosVendas();showToast('Proposta '+result.quote.num+' salva. Vendas e Obras continuam pelo fluxo de conferência.');}catch(e){showToast('Orçamento não confirmado: '+e.message,'warning');if(P.hasPending(localStorage))window.martinsMostrarRecuperacao?.();}finally{submit.disabled=false;}};
const add=window.adicionarLinhaItemOrcamento;window.adicionarLinhaItemOrcamento=function(...args){if(args[0]&&window.linhasOrcamentoModal?.length===1&&!window.linhasOrcamentoModal[0].desc){window.linhasOrcamentoModal=[];}add.apply(this,args);form.dispatchEvent(new Event('input',{bubbles:true}));};
})();
